 * @param newOpening 变更后开度，单位 %
 * @param createdAt  版本生成时间（UTC）
 */
public record ValveVersion(long id, long valveId, long taskId, int versionNo,
                           BigDecimal oldOpening, BigDecimal newOpening, Instant createdAt) {
}

