/**
 * 调节任务流转入口：效果评估与归档。
 */
@RestController
@RequestMapping("/api/tasks")
public class TaskController {

    private final AdjustmentService adjustmentService;

    public TaskController(AdjustmentService adjustmentService) {
        this.adjustmentService = adjustmentService;
    }

    /**
     * 评估请求。
