                + " (1, 1, 50.00, TIMESTAMP '2026-01-01 00:00:00'),"
                + " (2, 2, 50.00, TIMESTAMP '2026-01-01 00:00:00'),"
                + " (3, 3, 50.00, TIMESTAMP '2026-01-01 00:00:00'),"
                + " (4, 4, 50.00, TIMESTAMP '2026-01-01 00:00:00')");
        clock.set(T0);
