package com.example.starter.domain;

import java.time.Instant;

/**
 * 平衡阀铅封台账：登记唯一铅封号、封存时开度版本与封存时刻，复封保留历史封号链。
 *
 * @param id           主键
 * @param valveId      受控阀门 ID
 * @param sealCode     铅封号，全局唯一（含历史封号）
 * @param valveVersion 封存时阀门开度版本：无变更为 0，首次成功调节后为 1，逐次 +1
 * @param status       状态：ACTIVE 生效中 / RESEALED 已复封（历史封号，终态）
 * @param sealedAt     封存时刻（UTC）
 * @param resealedAt   复封终结时刻（UTC）；生效中为 null
 * @param createdAt    台账登记时间（UTC）
 */
public record ValveSeal(long id, long valveId, String sealCode, int valveVersion,
                        SealStatus status, Instant sealedAt, Instant resealedAt, Instant createdAt) {

    /**
     * 铅封状态机：ACTIVE → RESEALED（终态，历史封号保留）。
     */
    public enum SealStatus {
        /** 生效中：完整铅封下新的调节令必须拒绝。 */
        ACTIVE,
        /** 已复封：被新铅封终结的历史封号，仅保留证据。 */
        RESEALED
    }
}

package com.example.starter.domain;

import java.time.Instant;
import java.util.List;

/**
 * 临时解封单：引用铅封号与阀门版本，两名不同授权人确认，
 * 固定 UTC 半开窗口 [windowStart, windowEnd) 与最多两次调节额度。
 *
 * @param id           主键
 * @param sealId       引用的铅封台账 ID
 * @param valveId      受控阀门 ID（冗余自台账，便于按阀门串行化）
 * @param valveVersion 最近核对的阀门开度版本：批准时为申请值，每次消费额度后同步为最新版本
 * @param approvers    两名不同授权人（按字典序排序存储）
 * @param windowStart  解封有效窗口起点（UTC，含）
 * @param windowEnd    解封有效窗口终点（UTC，不含；恰到终点失效）
 * @param quotaTotal   调节额度上限，固定 2
 * @param quotaUsed    已消费调节额度，失败不消费
 * @param status       状态：ACTIVE 生效中 / REVOKED 已撤销 / CLOSED 已随复封终结
 * @param version      解封单自身版本，从 1 开始，每次成功变更 +1
 * @param revokedAt    撤销时刻（UTC）；未撤销为 null
 * @param closedAt     随复封终结时刻（UTC）；未终结为 null
 * @param createdAt    批准时间（UTC）
 */
public record UnsealPermit(long id, long sealId, long valveId, int valveVersion,
                           List<String> approvers, Instant windowStart, Instant windowEnd,
                           int quotaTotal, int quotaUsed, PermitStatus status, int version,
                           Instant revokedAt, Instant closedAt, Instant createdAt) {

    /** 调节额度上限：每张解封单最多两次调节。 */
    public static final int MAX_QUOTA = 2;

    /**
     * 解封单状态机：ACTIVE → REVOKED（撤销终态）/ CLOSED（复封终结终态）。
     */
    public enum PermitStatus {
        /** 生效中：窗口内可消费额度调节。 */
        ACTIVE,
        /** 已撤销：人工撤销，禁止新调节。 */
        REVOKED,
        /** 已终结：随复封原子终结，禁止新调节。 */
        CLOSED
    }
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 解封额度消费轨迹：每次受控调节消费一次额度时登记，与开度写入同事务。
 *
 * @param id             主键
 * @param permitId       解封单 ID
 * @param taskId         消费额度产生的调节任务 ID
 * @param valveVersion   消费后阀门开度版本
 * @param quotaUsedAfter 消费后已用额度
 * @param createdAt      消费时刻（UTC）
 */
public record QuotaEvent(long id, long permitId, long taskId, int valveVersion,
                         int quotaUsedAfter, Instant createdAt) {
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 新增写操作幂等台账：同键同参重放首次冻结结果，异参 409，失败不占键。
 *
 * @param requestId      客户端幂等键，全局唯一（主键）
 * @param fingerprint    结构化幂等指纹：操作类型与全部业务参数（含版本、集合、精确时刻）长度前缀编码的 SHA-256
 * @param operation      操作类型：SEAL_REGISTER / UNSEAL_APPROVE / UNSEAL_REVOKE / RESEAL / CONTROLLED_ADJUST
 * @param resultSnapshot 首次成功结果的冻结快照（JSON），同键同参重放时原样返回
 * @param createdAt      首次受理时间（UTC）
 */
public record IdempotencyRecord(String requestId, String fingerprint, String operation,
                                String resultSnapshot, Instant createdAt) {
}

